function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Bank' || !Array.isArray(args[0]) || args[0].length !== 1 || !Array.isArray(args[0][0])) return 'Start with Bank(balance).';
  const balance = args[0][0];
  if (balance.length < 1 || balance.length > 100000) return 'balance needs 1 to 10^5 accounts.';
  if (balance.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000000)) return 'Each starting balance is a whole number from 0 to 10^12.';
  const n = balance.length;
  const current = balance.slice();
  const goodAccount = (a) => Number.isInteger(a) && a >= 1 && a <= 100000;
  const goodMoney = (m) => Number.isInteger(m) && m >= 0 && m <= 1000000000000;
  const counts = { transfer: 0, deposit: 0, withdraw: 0 };
  for (let i = 1; i < operations.length; i++) {
    const name = operations[i];
    const a = args[i];
    if (!Object.hasOwn(counts, name)) return 'Only transfer, deposit and withdraw can follow the constructor.';
    if (++counts[name] > 10000) return 'At most 10^4 calls to each method.';
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (name === 'transfer') {
      if (a.length !== 3 || !goodAccount(a[0]) || !goodAccount(a[1])) return 'transfer needs two account numbers from 1 to 10^5 and an amount.';
      if (!goodMoney(a[2])) return 'money is a whole number from 0 to 10^12.';
      if (a[0] <= n && a[1] <= n && current[a[0] - 1] >= a[2]) {
        current[a[0] - 1] -= a[2];
        current[a[1] - 1] += a[2];
      }
    } else {
      if (a.length !== 2 || !goodAccount(a[0])) return name + ' needs an account number from 1 to 10^5 and an amount.';
      if (!goodMoney(a[1])) return 'money is a whole number from 0 to 10^12.';
      if (a[0] <= n && name === 'deposit') current[a[0] - 1] += a[1];
      if (a[0] <= n && name === 'withdraw' && current[a[0] - 1] >= a[1]) current[a[0] - 1] -= a[1];
    }
    if (a[0] <= n && current[a[0] - 1] > Number.MAX_SAFE_INTEGER || name === 'transfer' && a[1] <= n && current[a[1] - 1] > Number.MAX_SAFE_INTEGER) return 'Balances must stay below 2^53 here so they remain exact.';
  }
  return null;
}

