class Bank {
  constructor(balance) {
    this.balance = balance.slice();
    this.n = balance.length;
  }

  exists(account) {
    return account >= 1 && account <= this.n;
  }

  transfer(account1, account2, money) {
    if (!this.exists(account1) || !this.exists(account2)) {
      return false;
    }
    if (this.balance[account1 - 1] < money) {
      return false;
    }
    this.balance[account1 - 1] -= money;
    this.balance[account2 - 1] += money;
    return true;
  }

  deposit(account, money) {
    if (!this.exists(account)) {
      return false;
    }
    this.balance[account - 1] += money;
    return true;
  }

  withdraw(account, money) {
    if (!this.exists(account) || this.balance[account - 1] < money) {
      return false;
    }
    this.balance[account - 1] -= money;
    return true;
  }
}

