class Bank {
  constructor(balance) {
    this.accounts = new Map();
    balance.forEach((amount, index) => this.accounts.set(index + 1, amount));
  }
  move(from, to, money) {
    if (from !== null && !this.accounts.has(from)) return false;
    if (to !== null && !this.accounts.has(to)) return false;
    if (from !== null && this.accounts.get(from) < money) return false;
    if (from !== null) this.accounts.set(from, this.accounts.get(from) - money);
    if (to !== null) this.accounts.set(to, this.accounts.get(to) + money);
    return true;
  }
  transfer(account1, account2, money) {
    return this.move(account1, account2, money);
  }
  deposit(account, money) {
    return this.move(null, account, money);
  }
  withdraw(account, money) {
    return this.move(account, null, money);
  }
}

