function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1, 2000) : int(1, 5);
  const top = large ? 1000000000000 : rand() < 0.8 ? 50 : 1000000000000;
  const balance = Array.from({ length: n }, () => rand() < 0.15 ? 0 : int(0, top));
  const current = balance.slice();
  const calls = large ? 499 : int(1, 15);
  const operations = ['Bank'];
  const args = [[balance]];
  const account = () => {
    const roll = rand();
    if (roll < 0.1) return int(n + 1, 100000);
    if (roll < 0.15) return Math.min(n + 1, 100000);
    return int(1, n);
  };
  const amount = (from) => {
    const have = from >= 1 && from <= n ? current[from - 1] : top;
    const roll = rand();
    if (roll < 0.1) return 0;
    if (roll < 0.2) return Math.min(have, 1000000000000);
    if (roll < 0.35) return Math.min(have + int(1, 10), 1000000000000);
    return int(0, Math.min(have, 1000000000000));
  };
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < 0.4) {
      const from = account();
      const to = rand() < 0.1 ? from : account();
      const money = amount(from);
      operations.push('transfer');
      args.push([from, to, money]);
      if (from <= n && to <= n && current[from - 1] >= money) {
        current[from - 1] -= money;
        current[to - 1] += money;
      }
    } else if (roll < 0.7) {
      const to = account();
      const money = rand() < 0.1 ? 0 : int(0, top);
      operations.push('deposit');
      args.push([to, money]);
      if (to <= n) current[to - 1] += money;
    } else {
      const from = account();
      const money = amount(from);
      operations.push('withdraw');
      args.push([from, money]);
      if (from <= n && current[from - 1] >= money) current[from - 1] -= money;
    }
  }
  return [operations, args];
}
